from pathlib import Path

BASELINE = "5424a86"

def read(path):
    p = Path(path)
    if not p.exists():
        raise SystemExit(f"Missing {path}. Run from the sepulchria-portal repository root.")
    return p.read_text(encoding="utf-8")

def write(path, text):
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding="utf-8")
    print(f"✓ {path}")

write("app/(portal)/admin/missions/actions.ts", '"use server";\n\nimport { revalidatePath } from "next/cache";\n\nimport { requireAdminSection } from "@/lib/auth/require-staff";\nimport { createAdminClient } from "@/lib/supabase/admin";\nimport type {\n  AdminMissionActionState,\n} from "@/components/admin/admin-mission-form";\n\nfunction text(formData: FormData, key: string) {\n  return String(formData.get(key) ?? "").trim();\n}\n\nfunction success(message: string): AdminMissionActionState {\n  return { ok: true, message };\n}\n\nfunction failure(message: string): AdminMissionActionState {\n  return { ok: false, message };\n}\n\nexport async function updateDailyMissionDefinition(\n  _previousState: AdminMissionActionState,\n  formData: FormData,\n): Promise<AdminMissionActionState> {\n  await requireAdminSection("missions");\n\n  try {\n    const admin = createAdminClient();\n\n    const id = text(formData, "id");\n    const targetValue = Number(text(formData, "target_value"));\n    const rewardRemnants = Number(text(formData, "reward_remnants"));\n    const rewardItemQuantity = Number(text(formData, "reward_item_quantity"));\n    const rewardItemId = text(formData, "reward_item_id") || null;\n    const isActive = formData.get("is_active") === "on";\n    const countsToward =\n      formData.get("counts_toward_milestones") === "on";\n\n    if (!id) return failure("Mission is required.");\n\n    if (!Number.isSafeInteger(targetValue) || targetValue < 1) {\n      return failure("Target must be a positive whole number.");\n    }\n\n    if (!Number.isSafeInteger(rewardRemnants) || rewardRemnants < 0) {\n      return failure("Remnant reward must be zero or more.");\n    }\n\n    if (\n      !Number.isSafeInteger(rewardItemQuantity) ||\n      rewardItemQuantity < 0\n    ) {\n      return failure("Item quantity must be zero or more.");\n    }\n\n    const missionName =\n      text(formData, "name") || "Daily Mission";\n\n    const { error } = await admin\n      .from("daily_mission_definitions")\n      .update({\n        name: missionName,\n        description: text(formData, "description"),\n        target_value: targetValue,\n        difficulty: text(formData, "difficulty"),\n        reward_remnants: rewardRemnants,\n        reward_item_id: rewardItemId,\n        reward_item_quantity: rewardItemId ? rewardItemQuantity : 0,\n        is_active: isActive,\n        counts_toward_milestones: countsToward,\n      })\n      .eq("id", id);\n\n    if (error) return failure(error.message);\n\n    if (!isActive) {\n      const today = new Date().toISOString().slice(0, 10);\n\n      const { data: dayRows, error: dayError } = await admin\n        .from("daily_mission_days")\n        .select("id")\n        .eq("mission_date", today);\n\n      if (dayError) return failure(dayError.message);\n\n      const dayIds = (dayRows ?? []).map((row) => row.id);\n\n      if (dayIds.length > 0) {\n        const { error: assignmentError } = await admin\n          .from("daily_mission_assignments")\n          .update({\n            counts_toward_milestones: false,\n          })\n          .eq("mission_definition_id", id)\n          .in("day_id", dayIds);\n\n        if (assignmentError) {\n          return failure(assignmentError.message);\n        }\n      }\n    }\n\n    revalidatePath("/admin/missions");\n    revalidatePath("/missions");\n\n    return success(`${missionName} saved.`);\n  } catch (error) {\n    return failure(\n      error instanceof Error\n        ? error.message\n        : "Could not save mission.",\n    );\n  }\n}\n\nexport async function updateDailyMilestoneDefinition(\n  _previousState: AdminMissionActionState,\n  formData: FormData,\n): Promise<AdminMissionActionState> {\n  await requireAdminSection("missions");\n\n  try {\n    const admin = createAdminClient();\n\n    const milestoneKey = text(formData, "milestone_key");\n    const rewardRemnants = Number(text(formData, "reward_remnants"));\n    const rewardItemQuantity = Number(\n      text(formData, "reward_item_quantity"),\n    );\n    const rewardItemId = text(formData, "reward_item_id") || null;\n\n    if (!milestoneKey) return failure("Milestone is required.");\n\n    if (!Number.isSafeInteger(rewardRemnants) || rewardRemnants < 0) {\n      return failure("Remnant reward must be zero or more.");\n    }\n\n    if (\n      !Number.isSafeInteger(rewardItemQuantity) ||\n      rewardItemQuantity < 0\n    ) {\n      return failure("Item quantity must be zero or more.");\n    }\n\n    const milestoneName =\n      text(formData, "name") || "Daily Milestone";\n\n    const { error } = await admin\n      .from("daily_mission_milestone_definitions")\n      .update({\n        name: milestoneName,\n        description: text(formData, "description"),\n        reward_remnants: rewardRemnants,\n        reward_item_id: rewardItemId,\n        reward_item_quantity: rewardItemId ? rewardItemQuantity : 0,\n        is_active: formData.get("is_active") === "on",\n      })\n      .eq("milestone_key", milestoneKey);\n\n    if (error) return failure(error.message);\n\n    revalidatePath("/admin/missions");\n    revalidatePath("/missions");\n\n    return success(`${milestoneName} saved.`);\n  } catch (error) {\n    return failure(\n      error instanceof Error\n        ? error.message\n        : "Could not save milestone.",\n    );\n  }\n}\n\nexport type RewardPoolOwner =\n  | { type: "mission"; id: string }\n  | { type: "milestone"; id: string };\n\nexport type RewardPoolEntryInput = {\n  id?: string;\n  owner: RewardPoolOwner;\n  itemId: string;\n  chancePct: number;\n  quantity: number;\n  sortOrder: number;\n  isActive: boolean;\n};\n\nexport async function saveDailyMissionRewardPoolEntry(\n  input: RewardPoolEntryInput,\n) {\n  await requireAdminSection("missions");\n\n  const admin = createAdminClient();\n\n  if (!input.itemId) {\n    return { ok: false, message: "Choose an Item." };\n  }\n\n  if (\n    !Number.isSafeInteger(input.chancePct) ||\n    input.chancePct < 0 ||\n    input.chancePct > 100\n  ) {\n    return {\n      ok: false,\n      message: "Chance must be between 0 and 100.",\n    };\n  }\n\n  if (\n    !Number.isSafeInteger(input.quantity) ||\n    input.quantity < 1\n  ) {\n    return {\n      ok: false,\n      message: "Quantity must be at least 1.",\n    };\n  }\n\n  const values = {\n    mission_definition_id:\n      input.owner.type === "mission"\n        ? input.owner.id\n        : null,\n    milestone_key:\n      input.owner.type === "milestone"\n        ? input.owner.id\n        : null,\n    item_id: input.itemId,\n    chance_pct: input.chancePct,\n    quantity: input.quantity,\n    sort_order: input.sortOrder,\n    is_active: input.isActive,\n    updated_at: new Date().toISOString(),\n  };\n\n  const query = input.id\n    ? admin\n        .from("daily_mission_reward_pool_entries")\n        .update(values)\n        .eq("id", input.id)\n    : admin\n        .from("daily_mission_reward_pool_entries")\n        .insert(values);\n\n  const { error } = await query;\n\n  if (error) {\n    return { ok: false, message: error.message };\n  }\n\n  revalidatePath("/admin/missions");\n\n  return {\n    ok: true,\n    message: input.id ? "Pool Item saved." : "Pool Item added.",\n  };\n}\n\nexport async function deleteDailyMissionRewardPoolEntry(\n  entryId: string,\n) {\n  await requireAdminSection("missions");\n\n  const admin = createAdminClient();\n\n  const { error } = await admin\n    .from("daily_mission_reward_pool_entries")\n    .delete()\n    .eq("id", entryId);\n\n  if (error) {\n    return { ok: false, message: error.message };\n  }\n\n  revalidatePath("/admin/missions");\n\n  return { ok: true, message: "Pool Item removed." };\n}\n')
write("components/admin/daily-mission-reward-pool-editor.tsx", '"use client";\n\nimport {\n  useState,\n  useTransition,\n} from "react";\nimport { useRouter } from "next/navigation";\n\nimport {\n  deleteDailyMissionRewardPoolEntry,\n  saveDailyMissionRewardPoolEntry,\n  type RewardPoolOwner,\n} from "@/app/(portal)/admin/missions/actions";\n\ntype ItemOption = {\n  id: string;\n  name: string;\n};\n\ntype PoolEntry = {\n  id: string;\n  item_id: string;\n  chance_pct: number;\n  quantity: number;\n  sort_order: number;\n  is_active: boolean;\n};\n\ntype Feedback = {\n  ok: boolean;\n  message: string;\n} | null;\n\nfunction PoolRow({\n  owner,\n  items,\n  entry,\n  index,\n}: {\n  owner: RewardPoolOwner;\n  items: ItemOption[];\n  entry: PoolEntry;\n  index: number;\n}) {\n  const router = useRouter();\n  const [isPending, startTransition] = useTransition();\n  const [itemId, setItemId] = useState(entry.item_id);\n  const [chancePct, setChancePct] = useState(entry.chance_pct);\n  const [quantity, setQuantity] = useState(entry.quantity);\n  const [isActive, setIsActive] = useState(entry.is_active);\n  const [feedback, setFeedback] = useState<Feedback>(null);\n\n  function showFeedback(next: Feedback) {\n    setFeedback(next);\n    window.setTimeout(() => setFeedback(null), 5000);\n  }\n\n  function save() {\n    startTransition(async () => {\n      const result = await saveDailyMissionRewardPoolEntry({\n        id: entry.id,\n        owner,\n        itemId,\n        chancePct,\n        quantity,\n        sortOrder: entry.sort_order,\n        isActive,\n      });\n\n      showFeedback(result);\n      if (result.ok) router.refresh();\n    });\n  }\n\n  function remove() {\n    startTransition(async () => {\n      const result =\n        await deleteDailyMissionRewardPoolEntry(entry.id);\n\n      showFeedback(result);\n      if (result.ok) router.refresh();\n    });\n  }\n\n  return (\n    <div className="border border-[rgb(var(--sep-colour-59432c))]/35 bg-[rgb(var(--sep-colour-100c09))] p-3">\n      <div className="grid gap-3 md:grid-cols-[1fr_100px_100px_auto_auto_auto] md:items-end">\n        <label className="text-[9px] uppercase tracking-[0.14em] text-[rgb(var(--sep-colour-8f7858))]">\n          Item {index + 1}\n          <select\n            value={itemId}\n            onChange={(event) => setItemId(event.target.value)}\n            className="mt-1 w-full border border-[rgb(var(--sep-colour-59432c))]/55 bg-[rgb(var(--sep-colour-100c09))] px-3 py-2 normal-case tracking-normal text-xs text-[rgb(var(--sep-colour-d5c09b))] outline-none"\n          >\n            {items.map((item) => (\n              <option key={item.id} value={item.id}>\n                {item.name}\n              </option>\n            ))}\n          </select>\n        </label>\n\n        <label className="text-[9px] uppercase tracking-[0.14em] text-[rgb(var(--sep-colour-8f7858))]">\n          Chance %\n          <input\n            type="number"\n            min={0}\n            max={100}\n            step={1}\n            value={chancePct}\n            onChange={(event) =>\n              setChancePct(Number(event.target.value))\n            }\n            className="mt-1 w-full border border-[rgb(var(--sep-colour-59432c))]/55 bg-[rgb(var(--sep-colour-100c09))] px-3 py-2 normal-case tracking-normal text-xs text-[rgb(var(--sep-colour-d5c09b))] outline-none"\n          />\n        </label>\n\n        <label className="text-[9px] uppercase tracking-[0.14em] text-[rgb(var(--sep-colour-8f7858))]">\n          Quantity\n          <input\n            type="number"\n            min={1}\n            step={1}\n            value={quantity}\n            onChange={(event) =>\n              setQuantity(Number(event.target.value))\n            }\n            className="mt-1 w-full border border-[rgb(var(--sep-colour-59432c))]/55 bg-[rgb(var(--sep-colour-100c09))] px-3 py-2 normal-case tracking-normal text-xs text-[rgb(var(--sep-colour-d5c09b))] outline-none"\n          />\n        </label>\n\n        <label className="flex items-center gap-2 pb-2 text-xs text-[rgb(var(--sep-colour-bca886))]">\n          <input\n            type="checkbox"\n            checked={isActive}\n            onChange={(event) =>\n              setIsActive(event.target.checked)\n            }\n          />\n          Active\n        </label>\n\n        <button\n          type="button"\n          disabled={isPending}\n          onClick={save}\n          className="border border-[rgb(var(--sep-colour-765937))]/65 bg-[rgb(var(--sep-colour-21170f))] px-3 py-2 text-[9px] uppercase tracking-[0.14em] text-[rgb(var(--sep-colour-d9c092))] enabled:hover:border-[rgb(var(--sep-colour-a07945))] disabled:cursor-wait disabled:opacity-55"\n        >\n          {isPending ? "Saving..." : "Save"}\n        </button>\n\n        <button\n          type="button"\n          disabled={isPending}\n          onClick={remove}\n          className="border border-red-900/60 bg-red-950/20 px-3 py-2 text-[9px] uppercase tracking-[0.14em] text-red-300 enabled:hover:bg-red-950/35 disabled:cursor-wait disabled:opacity-55"\n        >\n          Remove\n        </button>\n      </div>\n\n      {feedback ? (\n        <p\n          className={[\n            "mt-2 text-right text-[10px]",\n            feedback.ok\n              ? "text-[rgb(var(--sep-colour-bfa471))]"\n              : "text-red-400",\n          ].join(" ")}\n        >\n          {feedback.message}\n        </p>\n      ) : null}\n    </div>\n  );\n}\n\nexport function DailyMissionRewardPoolEditor({\n  owner,\n  items,\n  entries,\n}: {\n  owner: RewardPoolOwner;\n  items: ItemOption[];\n  entries: PoolEntry[];\n}) {\n  const router = useRouter();\n  const [isPending, startTransition] = useTransition();\n  const [feedback, setFeedback] = useState<Feedback>(null);\n\n  function addItem() {\n    if (items.length === 0) {\n      setFeedback({\n        ok: false,\n        message: "There are no active Items available.",\n      });\n      return;\n    }\n\n    startTransition(async () => {\n      const nextSort =\n        entries.length > 0\n          ? Math.max(...entries.map((entry) => entry.sort_order)) + 10\n          : 10;\n\n      const result = await saveDailyMissionRewardPoolEntry({\n        owner,\n        itemId: items[0].id,\n        chancePct: 100,\n        quantity: 1,\n        sortOrder: nextSort,\n        isActive: true,\n      });\n\n      setFeedback(result);\n      window.setTimeout(() => setFeedback(null), 5000);\n\n      if (result.ok) router.refresh();\n    });\n  }\n\n  return (\n    <div className="mt-3 border-t border-[rgb(var(--sep-colour-59432c))]/30 pt-3">\n      <div className="flex items-center justify-between gap-4">\n        <div>\n          <p className="text-[8px] uppercase tracking-[0.17em] text-[rgb(var(--sep-colour-806b50))]">\n            Curated secondary Item pool\n          </p>\n\n          <p className="mt-1 text-[10px] leading-4 text-[rgb(var(--sep-colour-746856))]">\n            Evaluated from top to bottom. Each row gets its own chance roll;\n            the first successful Item wins. At most one secondary Item is awarded.\n          </p>\n        </div>\n\n        <button\n          type="button"\n          disabled={isPending}\n          onClick={addItem}\n          className="shrink-0 border border-[rgb(var(--sep-colour-765937))]/65 bg-[rgb(var(--sep-colour-21170f))] px-3 py-2 text-[9px] uppercase tracking-[0.14em] text-[rgb(var(--sep-colour-d9c092))] enabled:hover:border-[rgb(var(--sep-colour-a07945))] disabled:cursor-wait disabled:opacity-55"\n        >\n          {isPending ? "Adding..." : "+ Add Item"}\n        </button>\n      </div>\n\n      <div className="mt-3 space-y-2">\n        {entries.length === 0 ? (\n          <p className="border border-dashed border-[rgb(var(--sep-colour-59432c))]/35 px-3 py-3 text-xs text-[rgb(var(--sep-colour-847663))]">\n            No secondary Items configured.\n          </p>\n        ) : (\n          entries.map((entry, index) => (\n            <PoolRow\n              key={entry.id}\n              owner={owner}\n              items={items}\n              entry={entry}\n              index={index}\n            />\n          ))\n        )}\n      </div>\n\n      {feedback ? (\n        <p\n          className={[\n            "mt-2 text-right text-[10px]",\n            feedback.ok\n              ? "text-[rgb(var(--sep-colour-bfa471))]"\n              : "text-red-400",\n          ].join(" ")}\n        >\n          {feedback.message}\n        </p>\n      ) : null}\n\n      <p className="mt-2 text-[10px] leading-4 text-[rgb(var(--sep-colour-746856))]">\n        Pool changes affect future UTC Daily Mission snapshots only.\n        A fixed Reward Item above takes priority over this pool.\n      </p>\n    </div>\n  );\n}\n')

